// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).

use kayak_rt::*;
use super::*;

// read.kfx: the reader, from characters to `sexp`s, and taking them apart.

// Reading

// A list remembers where it began: its file's name, the line of its `(`,
// from 1, and its offset, in characters from 0; a number its file and
// offset. Messages say where (check.kfx's `refuse`), and the checker's
// facts about a place are keyed by its file and offset (`fact`), which no
// two nodes of a file share.
pub enum Sexp {
    Sym(Str, Str, i64),
    Str(Str, Str, i64),
    Num(i64, Str, i64),
    Big(Str, Str, i64),
    Chr(char, Str, i64),
    Lst(List<&'static Sexp>, Str, i64, i64),
    Real(Str, Str, i64),
}

pub fn sym(f0: Str, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Sym(f0, f1, f2))
}

pub fn str(f0: Str, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Str(f0, f1, f2))
}

pub fn num(f0: i64, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Num(f0, f1, f2))
}

pub fn big(f0: Str, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Big(f0, f1, f2))
}

pub fn chr(f0: char, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Chr(f0, f1, f2))
}

pub fn lst(f0: List<&'static Sexp>, f1: Str, f2: i64, f3: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Lst(f0, f1, f2, f3))
}

pub fn real(f0: Str, f1: Str, f2: i64) -> &'static Sexp {
    kayak_rt::heap_alloc(Sexp::Real(f0, f1, f2))
}

pub type Sexps = List<&'static Sexp>;

// Where reading is: the text left, its line, and its offset.
pub enum Here {
    Here(Chars, i64, i64),
}

pub fn here(f0: Chars, f1: i64, f2: i64) -> &'static Here {
    kayak_rt::heap_alloc(Here::Here(f0, f1, f2))
}

// A datum, and where reading is after it; the same for the items of a
// list; a token, the text after it, and its length, which a token's end
// leaves on its line.
pub enum Got {
    Got(&'static Sexp, &'static Here),
}

pub fn got(f0: &'static Sexp, f1: &'static Here) -> &'static Got {
    kayak_rt::heap_alloc(Got::Got(f0, f1))
}

pub enum Gots {
    Gots(Sexps, &'static Here),
}

pub fn gots(f0: Sexps, f1: &'static Here) -> &'static Gots {
    kayak_rt::heap_alloc(Gots::Gots(f0, f1))
}

pub enum Tok {
    Tok(Str, Chars, i64),
}

pub fn tok(f0: Str, f1: Chars, f2: i64) -> &'static Tok {
    kayak_rt::heap_alloc(Tok::Tok(f0, f1, f2))
}

pub fn read_error(file: Str, line: i64, message: Str) -> Void {
    error(string_append(str_lit("kfx: "), string_append(file, string_append(str_lit(":"), string_append(i64_to_string(line), string_append(str_lit(": "), message))))))
}

/// A comment's text, to the newline that ends it, which is left. The line
/// is not counted here, but by `skip`, which meets the newline.
pub fn skip_line(mut cs: Chars, mut pos: i64) -> &'static Here {
    loop {
        if null_p(cs) {
            return here(cs, 0i64, pos);
        } else if char_eq_p(car(cs), '\n') {
            return here(cs, 0i64, pos);
        } else {
            (cs, pos) = (cdr(cs), i64_plus(pos, 1i64));
            continue;
        }
    }
}

/// Skips whitespace and comments, counting lines and characters.
pub fn skip(mut h: &'static Here) -> &'static Here {
    loop {
        let tagcase_ = h;
        match *tagcase_ {
            Here::Here(cs, line, pos) => {
                if null_p(cs) {
                    return h;
                } else if char_eq_p(car(cs), '\n') {
                    h = here(cdr(cs), i64_plus(line, 1i64), i64_plus(pos, 1i64));
                    continue;
                } else if char_whitespace_p(car(cs)) {
                    h = here(cdr(cs), line, i64_plus(pos, 1i64));
                    continue;
                } else if char_eq_p(car(cs), ';') {
                    let tagcase_ = skip_line(cdr(cs), i64_plus(pos, 1i64));
                    match *tagcase_ {
                        Here::Here(rest, zero, after) => {
                            h = here(rest, line, after);
                            continue;
                        }
                    }
                } else {
                    return h;
                }
            }
        }
    }
}

pub fn delimiter_p(c: char) -> bool {
    (char_whitespace_p(c) || char_eq_p(c, '(') || char_eq_p(c, ')') || char_eq_p(c, '"') || char_eq_p(c, ';'))
}

/// A token's characters, onto `acc`, newest first, and `n`, how many.
pub fn token_chars(mut cs: Chars, mut acc: Chars, mut n: i64) -> &'static Tok {
    loop {
        if (null_p(cs) || delimiter_p(car(cs))) {
            return tok(rev_to_string(acc), cs, n);
        } else {
            (cs, acc, n) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc), i64_plus(n, 1i64));
            continue;
        }
    }
}

pub fn unescape(c: char) -> char {
    match c {
        'n' => {
            '\n'
        }
        't' => {
            '\t'
        }
        'r' => {
            i64_to_char(13i64)
        }
        _ => {
            c
        }
    }
}

/// R7RS's hex escape in a string (a backslash, `x41;`), after its `x`: the hex digits' value `n`,
/// `k` of them read, up to the `;`; the rest, as a token's text, the
/// character it names.
pub fn hex_escape(mut cs: Chars, mut n: i64, mut k: i64) -> &'static Tok {
    loop {
        if null_p(cs) {
            return tok(str_lit(""), cs, k);
        } else if i64_eq(char_to_i64(car(cs)), 59i64) {
            return tok(char_to_string(i64_to_char(n)), cdr(cs), i64_plus(k, 1i64));
        } else {
            let c = car(cs);
            let d = char_to_i64(c);
            (cs, n, k) = (cdr(cs), i64_plus(i64_star(n, 16i64), if (i64_gt_eq(d, 48i64) && i64_lt_eq(d, 57i64)) {
                i64_minus(d, 48i64)
            } else if (i64_gt_eq(d, 97i64) && i64_lt_eq(d, 102i64)) {
                i64_minus(d, 87i64)
            } else if (i64_gt_eq(d, 65i64) && i64_lt_eq(d, 70i64)) {
                i64_minus(d, 55i64)
            } else {
                0i64
            }), i64_plus(k, 1i64));
            continue;
        }
    }
}

/// A string's characters, after its opening quote on line `start`, at
/// offset `at`.
pub fn string_body(mut cs: Chars, mut acc: Chars, mut file: Str, mut start: i64, mut at: i64, mut line: i64, mut pos: i64) -> &'static Got {
    loop {
        if null_p(cs) {
            return match read_error(file, start, str_lit("a string is not closed")) {};
        } else if char_eq_p(car(cs), '"') {
            return got(str(rev_to_string(acc), file, at), here(cdr(cs), line, i64_plus(pos, 1i64)));
        } else if (char_eq_p(car(cs), '\\') && not(null_p(cdr(cs))) && i64_eq(char_to_i64(car(cdr(cs))), 120i64)) {
            let tagcase_ = hex_escape(cdr(cdr(cs)), 0i64, 0i64);
            match *tagcase_ {
                Tok::Tok(text, rest, k) => {
                    if string_eq_p(text, str_lit("")) {
                        return match read_error(file, start, str_lit("a string's hex escape is not closed by ;")) {};
                    } else {
                        (cs, acc, pos) = (rest, kayak_rt::heap_cons(string_ref_i64(text, 0i64), acc), i64_plus(pos, i64_plus(k, 2i64)));
                        continue;
                    }
                }
            }
        } else if char_eq_p(car(cs), '\\') {
            (cs, acc, pos) = (cdr(cdr(cs)), kayak_rt::heap_cons(unescape(car(cdr(cs))), acc), i64_plus(pos, 2i64));
            continue;
        } else if char_eq_p(car(cs), '\n') {
            (cs, acc, line, pos) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc), i64_plus(line, 1i64), i64_plus(pos, 1i64));
            continue;
        } else {
            (cs, acc, pos) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc), i64_plus(pos, 1i64));
            continue;
        }
    }
}

/// Digits onto `n`, negated: so that -9223372036854775808, whose
/// magnitude is no i64, reads. A literal past an i64 is refused, as FX-26
/// refuses it where an i64 is expected.
pub fn digits_value(mut cs: Chars, mut n: i64, mut file: Str, mut line: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let d = i64_minus(char_to_i64(car(cs)), 48i64);
            if (i64_lt(n, -922337203685477580i64) || (i64_eq(n, -922337203685477580i64) && i64_gt(d, 8i64))) {
                return match read_error(file, line, str_lit("a literal past an i64")) {};
            } else {
                (cs, n) = (cdr(cs), i64_minus(i64_star(n, 10i64), d));
                continue;
            }
        }
    }
}

pub fn numeric_p(cs: Chars) -> bool {
    (not(null_p(cs)) && (char_numeric_p(car(cs)) || (char_eq_p(car(cs), '-') && not(null_p(cdr(cs))) && char_numeric_p(car(cdr(cs))))))
}

pub fn has_char_p(cs: Chars, c: char) -> bool {
    (not(null_p(cs)) && (char_eq_p(car(cs), c) || has_char_p(cdr(cs), c)))
}

/// How many points `cs` has, or -1 if it has a character that is no
/// digit and no point.
pub fn point_count(mut cs: Chars, mut n: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else if char_eq_p(car(cs), '.') {
            (cs, n) = (cdr(cs), i64_plus(n, 1i64));
            continue;
        } else if char_numeric_p(car(cs)) {
            cs = cdr(cs);
            continue;
        } else {
            return -1i64;
        }
    }
}

/// Digits, after a `-` if any, with one point among them: a real, as FX-26
/// reads it (and Rust, written with a digit either side of the point).
pub fn real_token_p(cs: Chars) -> bool {
    i64_eq(point_count(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, 0i64), 1i64)
}

pub fn digits_after_zeros(mut cs: Chars) -> Chars {
    loop {
        if (not(null_p(cs)) && not(null_p(cdr(cs))) && char_eq_p(car(cs), '0')) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

/// Whether digits `cs` are at most `most`, of as many digits.
pub fn digits_at_most_p(mut cs: Chars, mut most: Chars) -> bool {
    loop {
        if null_p(cs) {
            return true;
        } else if i64_lt(char_to_i64(car(cs)), char_to_i64(car(most))) {
            return true;
        } else if i64_gt(char_to_i64(car(cs)), char_to_i64(car(most))) {
            return false;
        } else {
            (cs, most) = (cdr(cs), cdr(most));
            continue;
        }
    }
}

/// Whether an integer literal is an i64's; one past is an `int`'s alone.
pub fn fits_i64_p(cs: Chars) -> bool {
    let negative = char_eq_p(car(cs), '-');
    let ds = digits_after_zeros(if negative {
        cdr(cs)
    } else {
        cs
    });
    let n = size(ds);
    if i64_lt(n, 19i64) {
        true
    } else if i64_gt(n, 19i64) {
        false
    } else {
        digits_at_most_p(ds, string_chars(if negative {
            str_lit("9223372036854775808")
        } else {
            str_lit("9223372036854775807")
        }))
    }
}

// Reals as FX-26 reads them past KFX's own (C155): its point first, `.5`,
// or an exponent, `1e-3`, as Rust's `f64` syntax has them. kfx's
// restriction pass refuses both, KFX writing a real as it is written.
pub fn all_digits_p(cs: Chars) -> bool {
    (null_p(cs) || (char_numeric_p(car(cs)) && all_digits_p(cdr(cs))))
}

pub fn point_first_real_p(cs: Chars) -> bool {
    let body = if (not(null_p(cs)) && char_eq_p(car(cs), '-')) {
        cdr(cs)
    } else {
        cs
    };
    (not(null_p(body)) && char_eq_p(car(body), '.') && not(null_p(cdr(body))) && all_digits_p(cdr(body)))
}

/// A real's mantissa, before its `e`.
pub fn before_exponent(cs: Chars) -> Chars {
    if (null_p(cs) || char_eq_p(car(cs), 'e') || char_eq_p(car(cs), 'E')) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), before_exponent(cdr(cs)))
    }
}

/// A real's exponent, after its `e`; none if it has none.
pub fn after_exponent(mut cs: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return nil::<char>();
        } else if (char_eq_p(car(cs), 'e') || char_eq_p(car(cs), 'E')) {
            return cdr(cs);
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

/// `[-]M e [+-]D`, `M` digits with at most one point among them, `D`
/// digits.
pub fn exponent_real_p(cs: Chars) -> bool {
    let body = if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    };
    let m = before_exponent(body);
    let x = after_exponent(body);
    let ds = if (not(null_p(x)) && (char_eq_p(car(x), '+') || char_eq_p(car(x), '-'))) {
        cdr(x)
    } else {
        x
    };
    (not(null_p(ds)) && all_digits_p(ds) && not(null_p(filter(lambda1s(move |c: char| {
        char_numeric_p(c)
    }), m))) && i64_lt_eq(point_count(m, 0i64), 1i64) && all_digits_p(filter(lambda1s(move |c: char| {
        not(char_eq_p(c, '.'))
    }), m)))
}

/// Whether a real is written as KFX writes one: neither its point first nor
/// with an exponent.
pub fn written_out_real_p(t: Str) -> bool {
    let cs = string_chars(t);
    not((point_first_real_p(cs) || has_char_p(cs, 'e') || has_char_p(cs, 'E')))
}

/// Whether every character of `cs` is one of `allowed`'s.
pub fn only_of_p(cs: Chars, allowed: Str) -> bool {
    not(any_p(lambda1s(move |c: char| {
        not(has_char_p(string_chars(allowed), c))
    }), cs))
}

pub fn before_point(cs: Chars) -> Chars {
    if (null_p(cs) || char_eq_p(car(cs), '.')) {
        nil::<char>()
    } else {
        kayak_rt::heap_cons(car(cs), before_point(cdr(cs)))
    }
}

/// Hex digits onto `n`, as `digits-value`'s are, negated; one past an i64
/// refused (C116: Fixpt's arm64 encoder writes its instructions so).
pub fn hex_value(mut cs: Chars, mut n: i64, mut file: Str, mut line: i64) -> i64 {
    loop {
        if null_p(cs) {
            return n;
        } else {
            let c = char_downcase(car(cs));
            let d = if char_numeric_p(c) {
                i64_minus(char_to_i64(c), 48i64)
            } else {
                i64_plus(10i64, i64_minus(char_to_i64(c), 97i64))
            };
            if i64_lt(n, -576460752303423487i64) {
                return match read_error(file, line, str_lit("a hex literal past an i64, which KFX reads not yet")) {};
            } else {
                (cs, n) = (cdr(cs), i64_minus(i64_star(n, 16i64), d));
                continue;
            }
        }
    }
}

pub fn token_atom(s: Str, file: Str, line: i64, pos: i64) -> &'static Sexp {
    let cs = string_chars(s);
    if (char_eq_p(car(cs), '#') && not(null_p(cdr(cs))) && (char_eq_p(car(cdr(cs)), 'x') || char_eq_p(car(cdr(cs)), 'X')) && not(null_p(cdr(cdr(cs))))) {
        // A hex literal, `#x1f`, `#x-1f`, R7RS's, as FX-26 reads it.
        let ds = cdr(cdr(cs));
        let negative = char_eq_p(car(ds), '-');
        let ds = if (negative || char_eq_p(car(ds), '+')) {
            cdr(ds)
        } else {
            ds
        };
        if (null_p(ds) || not(only_of_p(ds, str_lit("0123456789abcdefABCDEF")))) {
            match read_error(file, line, string_append(str_lit("no number KFX reads: "), s)) {}
        } else {
            let n = hex_value(ds, 0i64, file, line);
            if negative {
                num(n, file, pos)
            } else {
                if i64_eq(n, -9223372036854775808i64) {
                    match read_error(file, line, str_lit("a hex literal past an i64, which KFX reads not yet")) {}
                } else {
                    num(i64_minus(0i64, n), file, pos)
                }
            }
        }
    } else if point_first_real_p(cs) {
        real(s, file, pos)
    } else if not(numeric_p(cs)) {
        sym(s, file, pos)
    } else if not(only_of_p(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, str_lit("0123456789.eE+-"))) {
        // Not a number, though a digit begins it (`1x`, `0x10`): a name, as
        // FX-26 reads it.
        sym(s, file, pos)
    } else if (has_char_p(cs, 'e') || has_char_p(cs, 'E')) {
        if exponent_real_p(cs) {
            real(s, file, pos)
        } else {
            match read_error(file, line, string_append(str_lit("no number KFX reads: "), s)) {}
        }
    } else if has_char_p(cs, '.') {
        if (real_token_p(cs) && only_of_p(if char_eq_p(car(cs), '-') {
            cdr(cs)
        } else {
            cs
        }, str_lit("0123456789."))) {
            if i64_gt(size(digits_after_zeros(before_point(if char_eq_p(car(cs), '-') {
                cdr(cs)
            } else {
                cs
            }))), 21i64) {
                match read_error(file, line, string_append(str_lit("a real of 1e21 or more, which FX-26 reads as an int: "), s)) {}
            } else {
                real(s, file, pos)
            }
        } else {
            match read_error(file, line, string_append(str_lit("no number KFX reads: "), s)) {}
        }
    } else if not(only_of_p(if char_eq_p(car(cs), '-') {
        cdr(cs)
    } else {
        cs
    }, str_lit("0123456789"))) {
        match read_error(file, line, string_append(str_lit("no number KFX reads: "), s)) {}
    } else if not(fits_i64_p(cs)) {
        big(s, file, pos)
    } else if char_eq_p(car(cs), '-') {
        num(digits_value(cdr(cs), 0i64, file, line), file, pos)
    } else {
        num(i64_minus(0i64, digits_value(cs, 0i64, file, line)), file, pos)
    }
}

pub fn char_named(s: Str, file: Str, line: i64) -> char {
    if i64_eq(string_length_i64(s), 1i64) {
        string_ref_i64(s, 0i64)
    } else if string_eq_p(s, str_lit("space")) {
        ' '
    } else if string_eq_p(s, str_lit("newline")) {
        '\n'
    } else if string_eq_p(s, str_lit("tab")) {
        '\t'
    } else {
        match read_error(file, line, string_append(str_lit("no character is named "), s)) {}
    }
}

/// A datum at the start of `h`'s text, which `file` holds.
pub fn read_datum(h: &'static Here, file: Str) -> &'static Got {
    let tagcase_ = h;
    match *tagcase_ {
        Here::Here(cs, line, pos) => {
            let c = car(cs);
            if char_eq_p(c, '(') {
                let tagcase_ = read_items(here(cdr(cs), line, i64_plus(pos, 1i64)), file);
                match *tagcase_ {
                    Gots::Gots(xs, after) => {
                        got(lst(xs, file, line, pos), after)
                    }
                }
            } else if char_eq_p(c, ')') {
                match read_error(file, line, str_lit("a ) with no (")) {}
            } else if (i64_eq(char_to_i64(c), 39i64) && not(null_p(cdr(cs))) && not(string_eq_p(file, str_lit("")))) {
                // `'d`, FX-26's `(quote d)` (C56), in a program's text; in the
                // checker's own (a file named ``), `'r` is a region binder's name.
                let tagcase_ = read_datum(skip(here(cdr(cs), line, i64_plus(pos, 1i64))), file);
                match *tagcase_ {
                    Got::Got(x, after) => {
                        got(lst(kayak_rt::heap_cons(sym(str_lit("quote"), file, pos), kayak_rt::heap_cons(x, kayak_rt::nil())), file, line, pos), after)
                    }
                }
            } else if ((i64_eq(char_to_i64(c), 96i64) || i64_eq(char_to_i64(c), 44i64)) && not(null_p(cdr(cs))) && not(string_eq_p(file, str_lit("")))) {
                // `` `d ``, `,d` and `,@d`: FX-26's `quasiquote`, `unquote` and
                // `unquote-splicing` (C79), in a program's text.
                let splice = (i64_eq(char_to_i64(c), 44i64) && char_eq_p(car(cdr(cs)), '@'));
                let rest = if splice {
                    cdr(cdr(cs))
                } else {
                    cdr(cs)
                };
                let head = if i64_eq(char_to_i64(c), 96i64) {
                    str_lit("quasiquote")
                } else if splice {
                    str_lit("unquote-splicing")
                } else {
                    str_lit("unquote")
                };
                let tagcase_ = read_datum(skip(here(rest, line, i64_plus(pos, if splice {
                    2i64
                } else {
                    1i64
                }))), file);
                match *tagcase_ {
                    Got::Got(x, after) => {
                        got(lst(kayak_rt::heap_cons(sym(head, file, pos), kayak_rt::heap_cons(x, kayak_rt::nil())), file, line, pos), after)
                    }
                }
            } else if (char_eq_p(c, '#') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '(') && not(string_eq_p(file, str_lit("")))) {
                // `#(d ...)`, a vector (C80): `(#vector d ...)`, a head no KFX name
                // is, which only a quote takes.
                let tagcase_ = read_items(here(cdr(cdr(cs)), line, i64_plus(pos, 2i64)), file);
                match *tagcase_ {
                    Gots::Gots(xs, after) => {
                        got(lst(kayak_rt::heap_cons(sym(str_lit("#vector"), file, pos), xs), file, line, pos), after)
                    }
                }
            } else if char_eq_p(c, '"') {
                string_body(cdr(cs), nil::<char>(), file, line, pos, line, i64_plus(pos, 1i64))
            } else if (char_eq_p(c, '#') && not(null_p(cdr(cs))) && char_eq_p(car(cdr(cs)), '\\')) {
                let name = cdr(cdr(cs));
                let tagcase_ = token_chars(cdr(name), kayak_rt::heap_cons(car(name), kayak_rt::nil()), 1i64);
                match *tagcase_ {
                    Tok::Tok(s, after, n) => {
                        got(chr(char_named(s, file, line), file, pos), here(after, line, i64_plus(pos, i64_plus(n, 2i64))))
                    }
                }
            } else {
                let tagcase_ = token_chars(cs, nil::<char>(), 0i64);
                match *tagcase_ {
                    Tok::Tok(s, after, n) => {
                        got(token_atom(s, file, line, pos), here(after, line, i64_plus(pos, n)))
                    }
                }
            }
        }
    }
}

pub fn read_items(h: &'static Here, file: Str) -> &'static Gots {
    let h = skip(h);
    let tagcase_ = h;
    match *tagcase_ {
        Here::Here(cs, line, pos) => {
            if null_p(cs) {
                match read_error(file, line, str_lit("a ( with no )")) {}
            } else if char_eq_p(car(cs), ')') {
                gots(nil::<&'static Sexp>(), here(cdr(cs), line, i64_plus(pos, 1i64)))
            } else {
                let tagcase_ = read_datum(h, file);
                match *tagcase_ {
                    Got::Got(x, after) => {
                        let tagcase_ = read_items(after, file);
                        match *tagcase_ {
                            Gots::Gots(xs, rest) => {
                                gots(kayak_rt::heap_cons(x, xs), rest)
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn read_from(h: &'static Here, file: Str) -> Sexps {
    let h = skip(h);
    let tagcase_ = h;
    match *tagcase_ {
        Here::Here(cs, line, pos) => {
            if null_p(cs) {
                nil::<&'static Sexp>()
            } else {
                let tagcase_ = read_datum(h, file);
                match *tagcase_ {
                    Got::Got(x, after) => {
                        kayak_rt::heap_cons(x, read_from(after, file))
                    }
                }
            }
        }
    }
}

/// Every datum in `cs`, the text of `file` from `line`.
pub fn read_all(cs: Chars, file: Str, line: i64) -> Sexps {
    read_from(here(cs, line, 0i64), file)
}

// Taking `sexp`s apart
/// The file a datum was read from; ``, for one the compiler made.
pub fn datum_file(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, file, pos) => {
            file
        }
        Sexp::Str(t, file, pos) => {
            file
        }
        Sexp::Num(i, file, pos) => {
            file
        }
        Sexp::Big(t, file, pos) => {
            file
        }
        Sexp::Chr(c, file, pos) => {
            file
        }
        Sexp::Lst(xs, file, line, pos) => {
            file
        }
        Sexp::Real(t, file, pos) => {
            file
        }
    }
}

/// Where in its file a datum begins.
pub fn datum_pos(e: &'static Sexp) -> i64 {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, file, pos) => {
            pos
        }
        Sexp::Str(t, file, pos) => {
            pos
        }
        Sexp::Num(i, file, pos) => {
            pos
        }
        Sexp::Big(t, file, pos) => {
            pos
        }
        Sexp::Chr(c, file, pos) => {
            pos
        }
        Sexp::Lst(xs, file, line, pos) => {
            pos
        }
        Sexp::Real(t, file, pos) => {
            pos
        }
    }
}

pub fn sym_name(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(s, at_file, at_pos) => {
            s
        }
        _ => {
            let other = tagcase_;
            error(str_lit("kfx: a name is expected"))
        }
    }
}

pub fn sym_is_p(e: &'static Sexp, s: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, at_file, at_pos) => {
            string_eq_p(n, s)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn items(e: &'static Sexp) -> Sexps {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            xs
        }
        _ => {
            let other = tagcase_;
            error(str_lit("kfx: a list is expected"))
        }
    }
}

pub fn head_is_p(e: &'static Sexp, s: Str) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            (not(null_p(xs)) && sym_is_p(car(xs), s))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A type `(subr (conv C) E (T ...) R)` as `(subr E (T ...) R)`: a native
/// procedure is in Rust as any is (C116), so past the checker no pass
/// need know its convention.
pub fn without_conv(t: &'static Sexp) -> &'static Sexp {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            if (head_is_p(t, str_lit("subr")) && i64_eq(size(xs), 5i64) && head_is_p(car(cdr(xs)), str_lit("conv"))) {
                lst(kayak_rt::heap_cons(car(xs), cdr(cdr(xs))), f, l, p)
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn second(xs: Sexps) -> &'static Sexp {
    car(cdr(xs))
}

pub fn third(xs: Sexps) -> &'static Sexp {
    car(cdr(cdr(xs)))
}

pub fn fourth(xs: Sexps) -> &'static Sexp {
    car(cdr(cdr(cdr(xs))))
}

/// A lambda's parameter's name: it is `x` or `(x T)`.
pub fn param_name(param: &'static Sexp) -> Str {
    sym_name({
        let tagcase_ = param;
        match *tagcase_ {
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                car(xs)
            }
            _ => {
                let other = tagcase_;
                other
            }
        }
    })
}

pub fn lambda_form_p(e: &'static Sexp) -> bool {
    (head_is_p(e, str_lit("lambda")) || head_is_p(e, str_lit("plambda")))
}

